-\vspace{0.35cm}\noindent\textbf{\large A. Définition et propriétés algébriques}\par\vspace{0.15cm}
-\begin{enumerate}
-  \item \textbf{Définition :} La fonction logarithme népérien, notée $\ln$, est la primitive de la fonction $x \mapsto \frac{1}{x}$ sur l'intervalle $]0 ; +\infty[$ qui s'annule en $1$. C'est une fonction définie, continue et dérivable (donc de classe $\mathcal{C}^\infty$) sur $]0 ; +\infty[$.
-  \item \textbf{Relation fondamentale :} Pour tous réels $a > 0$ et $b > 0$ :
-\end{enumerate}
-$$\ln(a \times b) = \ln(a) + \ln(b)$$
-\begin{enumerate}
-  \item \textbf{Conséquences algébriques :}
-  \item $\ln\left(\frac{1}{a}\right) = -\ln(a)$
-  \item $\ln\left(\frac{a}{b}\right) = \ln(a) - \ln(b)$
-  \item $\ln(a^n) = n\ln(a)$ pour tout entier $n$ (et plus généralement $\ln(a^r) = r\ln(a)$ pour tout rationnel $r$).
-  \item \textbf{Lien avec l'exponentielle :}
-  \item Pour tout $x \in ]0 ; +\infty[$, $e^{\ln(x)} = x$.
-  \item Pour tout $x \in \mathbb{R}$, $\ln(e^x) = x$.
-  \item En particulier, $\ln(1) = 0$ et $\ln(e) = 1$.
-\end{enumerate}
-
-\vspace{0.35cm}\noindent\textbf{\large B. Étude analytique et limites fondamentales}\par\vspace{0.15cm}
-\begin{enumerate}
-  \item \textbf{Sens de variation :} La dérivée de $\ln$ est $\ln'(x) = \frac{1}{x}$. Pour tout $x > 0$, $\frac{1}{x} > 0$, donc \textbf{la fonction $\ln$ est strictement croissante} sur $]0 ; +\infty[$.
-  \item \textbf{Limites aux bornes :}
-\end{enumerate}
-$$\lim\_{x \to 0^+} \ln(x) = -\infty \quad \text{et} \quad \lim\_{x \to +\infty} \ln(x) = +\infty$$
-\begin{enumerate}
-  \item \textbf{Croissances comparées (essentielles en Terminale) :}
-\end{enumerate}
-$$\lim\_{x \to +\infty} \frac{\ln(x)}{x} = 0 \quad \text{et} \quad \lim\_{x \to 0^+} x \ln(x) = 0$$
-Plus généralement, pour tout entier $n \ge 1$ : $\lim_{x \to +\infty} \frac{\ln(x)}{x^n} = 0$ et $\lim_{x \to 0^+} x^n \ln(x) = 0$.
-
-\vspace{0.35cm}\noindent\textbf{\large C. Convexité et dérivée seconde}\par\vspace{0.15cm}
-\begin{enumerate}
-  \item La dérivée seconde de $\ln$ est $\ln''(x) = -\frac{1}{x^2}$.
-  \item Pour tout $x > 0$, $\ln''(x) < 0$, ce qui signifie que \textbf{la fonction logarithme népérien est strictement concave} sur $]0 ; +\infty[$. Sa courbe représentative est entièrement située en dessous de chacune de ses tangentes.
-\end{enumerate}
-
